WITH enriched AS (SELECT *, NTILE(5) OVER w_ordered AS cost_bucket, AVG(stock_qty) OVER (PARTITION BY supplier_id ORDER BY price, id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS stock_qty_avg_3_prior, LEAD(price, 1) OVER w_part AS next_price FROM products WINDOW w_ordered AS (PARTITION BY category, supplier_id ORDER BY cost, id), w_part AS (PARTITION BY brand ORDER BY stock_qty, id)) SELECT brand, MAX(price) FILTER (WHERE brand = 'Globex') AS globex_max_price, COUNT(DISTINCT brand) AS distinct_brands, COUNT(DISTINCT brand) AS distinct_brands_2 FROM enriched GROUP BY brand HAVING globex_max_price >= 0 ORDER BY globex_max_price;
